#define MAXN 200005

typedef struct Edge {
    int to;
    struct Edge *next;
} Edge;

Edge *adj[MAXN];
int indeg[MAXN];
int salary[MAXN];
int queue[MAXN];
int n, m;

void add_edge(int u, int v) {
    Edge *e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->next = adj[u];
    adj[u] = e;
}

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 0; i < m; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        // a contributes more than b, so a must earn > b
        add_edge(b, a);  // edge b -> a means a depends on b
        indeg[a]++;
    }

    int front = 0, rear = 0;
    for (int i = 1; i <= n; i++) {
        if (indeg[i] == 0) {
            queue[rear++] = i;
            salary[i] = 1;
        }
    }

    int visited = 0;
    while (front < rear) {
        int u = queue[front++];
        visited++;
        for (Edge *e = adj[u]; e; e = e->next) {
            int v = e->to;
            if (salary[v] < salary[u] + 1)
                salary[v] = salary[u] + 1;
            if (--indeg[v] == 0) {
                queue[rear++] = v;
            }
        }
