#define MAXN 100005

int n, m;
int contrib[MAXN];
int salary[MAXN];
int indegree[MAXN];
// adjacency list
int head[MAXN], nxt[MAXN*2], to[MAXN*2], ecnt;

void addEdge(int u, int v) {
    ecnt++;
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
    indegree[v]++;
}

int queue[MAXN];

int main() {
    scanf("%d %d", &n, &m);
    for (int i = 1; i <= n; i++) scanf("%d", &contrib[i]);

    memset(head, 0, sizeof(head));
    memset(indegree, 0, sizeof(indegree));
    ecnt = 0;

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        if (contrib[u] > contrib[v]) addEdge(v, u);
        else if (contrib[v] > contrib[u]) addEdge(u, v);
        // equal contribution: no constraint
    }

    // Topological sort + DP for longest path
    for (int i = 1; i <= n; i++) salary[i] = 1;

    int front = 0, back = 0;
    for (int i = 1; i <= n; i++) {
        if (indegree[i] == 0) queue[back++] = i;
    }

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if (salary[v] < salary[u] + 1) salary[v] = salary[u] + 1;
            indegree[v]--;
            if (indegree[v] == 0) queue[back++] = v;
        }
    }

    long long total = 0;
    for (int i = 1; i <= n; i++) total += salary[i];
    printf("%lld\n", total);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int val;
    int idx;
} Node;

int cmpNode(const void *a, const void *b) {
    Node *x = (Node *)a;
    Node *y = (Node *)b;
    if (x->val < y->val) return -1;
    if (x->val > y->val) return 1;
    return 0;
}

int main() {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *a = (int *)malloc(sizeof(int) * N);
    Node *arr = (Node *)malloc(sizeof(Node) * N);
    long long *salary = (long long *)malloc(sizeof(long long) * N);

    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
        arr[i].val = a[i];
        arr[i].idx = i;
        salary[i] = 1;
    }

    qsort(arr, N, sizeof(Node), cmpNode);

    for (int i = 0; i < N; ) {
        int j = i;
        while (j < N && arr[j].val == arr[i].val) j++;

        for (int k = i; k < j; k++) {
            int idx = arr[k].idx;
            long long best = 1;

            if (idx > 0 && a[idx] > a[idx - 1]) {
                if (salary[idx - 1] + 1 > best) best = salary[idx - 1] + 1;
            }
            if (idx + 1 < N && a[idx] > a[idx + 1]) {
                if (salary[idx + 1] + 1 > best) best = salary[idx + 1] + 1;
            }
            salary[idx] = best;
        }

        i = j;
    }

    long long ans = 0;
    for (int i = 0; i < N; i++) ans += salary[i];

    printf("%lld\n", ans);

    free(a);
    free(arr);
    free(salary);
    return 0;
}

