int main() {
    int n, m;
    cin >> n >> m;

    vector<int> c(n);
    for (int i = 0; i < n; i++) cin >> c[i];

    // Build DAG of constraints
    vector<vector<int>> adj(n);
    vector<int> indegree(n, 0);

    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        if (c[u] > c[v]) {
            adj[v].push_back(u); // u needs higher salary
            indegree[u]++;
        } else if (c[v] > c[u]) {
            adj[u].push_back(v);
            indegree[v]++;
        }
    }

    // Topological sort + longest path
    vector<int> dist(n, 1);
    queue<int> q;
    for (int i = 0; i < n; i++) if (indegree[i] == 0) q.push(i);

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int v : adj[u]) {
            dist[v] = max(dist[v], dist[u] + 1);
            if (--indegree[v] == 0) q.push(v);
        }
    }

    long long sum = 0;
    for (int i = 0; i < n; i++) sum += dist[i];
    cout << sum << endl;

    return 0;
}

