    int N;
    if (!(cin >> N)) return 0;

    vector<int> a(N);
    for (int i = 0; i < N; ++i) cin >> a[i];

    vector<long long> left(N, 1), right(N, 1);

    for (int i = 1; i < N; ++i) {
        if (a[i] > a[i - 1]) left[i] = left[i - 1] + 1;
    }

    for (int i = N - 2; i >= 0; --i) {
        if (a[i] > a[i + 1]) right[i] = right[i + 1] + 1;
    }

    long long ans = 0;
    for (int i = 0; i < N; ++i) {
        ans += max(left[i], right[i]);
    }

    cout << ans << '\n';
    return 0;
}

