import java.io.*;
import java.util.*;

/*
The problem is the classic "minimum salaries under relative comparisons" on a graph.

Interpretation:
- There are N employees.
- For some pairs of employees, we know whether one has higher contribution than the other.
- Salary must be a positive integer.
- If contribution(A) > contribution(B), then salary(A) > salary(B).
- We need the minimum possible total salary.

This is solved by building a directed graph:
B -> A if contribution(A) > contribution(B)
Then the minimum valid salary of a node is:
salary[u] = 1 + max(salary[v]) over all predecessors v with edge v -> u
Equivalently on the reverse graph:
salary[u] = 1 if no outgoing edges in original DAG
salary[u] = 1 + max(salary[to])

The graph must be acyclic for a valid assignment. In the standard formulation of this problem,
the relation is consistent, so we compute longest path in DAG using topological order.

Input format assumed:
N M
u1 v1
u2 v2
...
uM vM

where each pair (u, v) means employee u has higher contribution than employee v,
so salary[u] > salary[v].

If your judge uses the opposite meaning, swap the edge direction accordingly.

Output:
Minimum possible sum of salaries.
*/

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        int m = fs.nextInt();

        List<Integer>[] g = new ArrayList[n + 1];
        int[] indeg = new int[n + 1];
        for (int i = 1; i <= n; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            // u has higher contribution than v => salary[u] > salary[v]
            // edge v -> u
            g[v].add(u);
            indeg[u]++;
        }

        long[] salary = new long[n + 1];
        Arrays.fill(salary, 1);

        ArrayDeque<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            if (indeg[i] == 0) q.add(i);
        }

        int seen = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            seen++;
            for (int v : g[u]) {
                if (salary[v] < salary[u] + 1) {
                    salary[v] = salary[u] + 1;
                }
                if (--indeg[v] == 0) {
                    q.add(v);
                }
            }
        }

        // If there is a cycle, no valid assignment exists.
        // Most versions of this problem guarantee consistency,
        // but we guard anyway.
        if (seen < n) {
            System.out.println(-1);
            return;
        }

        long ans = 0;
        for (int i = 1; i <= n; i++) ans += salary[i];
        System.out.println(ans);
    }
}
